import argparse
def positive(s):
 n=int(s)
 if n<=0: raise argparse.ArgumentTypeError("must be positive")
 return n
def page_size(size):
 if size<=0: raise ValueError("size must be positive")
 return size
def main(argv=None):
 p=argparse.ArgumentParser(); p.add_argument("--size",type=positive,default=10); a=p.parse_args(argv); print(page_size(a.size))
if __name__=="__main__": main()

