from urllib.parse import parse_qs
def list_items(query):
 p=parse_qs(query,keep_blank_values=True); raw=p.get("limit",[None])[0]; limit=20 if raw is None else int(raw); return [f"row-{i}" for i in range(limit)]
def app(environ,start_response):
 body=repr(list_items(environ.get("QUERY_STRING",""))).encode(); start_response("200 OK",[("Content-Type","text/plain")]); return [body]

